import{_ as a,o as i,c as n,ai as e}from"./chunks/framework.ampVZV4B.js";const g=JSON.parse('{"title":"服务监控与告警","description":"","frontmatter":{},"headers":[],"relativePath":"apps/ops/monitor-alert.md","filePath":"apps/ops/monitor-alert.md"}'),t={name:"apps/ops/monitor-alert.md"};function l(p,s,r,h,k,d){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="服务监控与告警" tabindex="-1">服务监控与告警 <a class="header-anchor" href="#服务监控与告警" aria-label="Permalink to “服务监控与告警”">​</a></h1><h2 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to “背景与问题”">​</a></h2><p>服务上线后的典型状态是：<strong>坏了才知道，而且是用户先知道</strong>。页面打不开，客服截图进来，运维登上服务器才发现进程半夜就挂了；或者更糟——进程活着但接口已经不可用，健康检查绿的，用户投诉红的。</p><p>另一个极端是告警泛滥：阈值随手拍脑袋，磁盘 80% 报、CPU 60% 报，夜里微信群一响全是噪声，值班的从「紧张」练成「免疫」，真出事的那条也被划走。<strong>告警的价值不在数量，在于每一条都值得被叫醒。</strong></p><p>监控要回答的其实只有三个问题：现在活着吗（可用性）、活得健康吗（性能指标）、出事时链路上哪一环断了（定位）。对应到数据就是日志、指标、链路三类，缺一类，排查就得靠猜。</p><h2 id="方案设计" tabindex="-1">方案设计 <a class="header-anchor" href="#方案设计" aria-label="Permalink to “方案设计”">​</a></h2><p>三层数据 + 一条告警链路：</p><table tabindex="0"><thead><tr><th>层</th><th>数据</th><th>作用</th><th>常用组件</th></tr></thead><tbody><tr><td>日志</td><td>应用/系统/Nginx 日志</td><td>出事后定位具体错误</td><td>Loki / ELK，容器场景直接 stdout 收集</td></tr><tr><td>指标</td><td>QPS、延迟、错误率、资源</td><td>判断&quot;活得好不好&quot;、触发告警</td><td>Prometheus + node/container exporter</td></tr><tr><td>链路</td><td>跨服务调用耗时</td><td>分清是自己慢还是下游慢</td><td>OpenTelemetry → Tempo/Jaeger</td></tr></tbody></table><p>配套组件：Grafana 统一看板，Alertmanager 做告警路由与降噪，Uptime Kuma 之类做「外部拨测」（从用户视角确认可达）。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Exporter/SDK ──▶ Prometheus ──▶ 告警规则 ──▶ Alertmanager ──▶ IM/电话</span></span>
<span class="line"><span>应用日志 ──▶ Loki ──▶ Grafana（按 trace_id 关联）──▶ 跳转 Tempo 看链路</span></span>
<span class="line"><span>外部拨测 ──▶ Uptime Kuma ──▶ 服务真不可达时兜底告警</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>SLI/告警的核心三指标</strong>：延迟（P95）、流量、错误率，外加饱和度（磁盘/内存/连接池）。这四个出问题基本能覆盖绝大多数故障模式。</p><h2 id="关键实现" tabindex="-1">关键实现 <a class="header-anchor" href="#关键实现" aria-label="Permalink to “关键实现”">​</a></h2><p><strong>1. 健康检查要分层</strong>，别一个 <code>/health</code> 混到底：</p><ul><li><strong>存活（liveness）</strong>：进程还能不能服务，失败就重启容器——但不要把依赖检查塞进来，否则数据库抖一下就全体重启放大故障；</li><li><strong>就绪（readiness）</strong>：依赖（DB、缓存）可达吗，失败就摘出流量，不重启；</li><li><strong>深度检查</strong>：关键依赖 + 核心链路探活，频率低，供告警用。</li></ul><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># k8s/compose 里探针的分工示意</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">livenessProbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GET /healthz</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 只查进程与关键线程</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">readinessProbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GET /readyz</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 查 DB/Redis 连通，失败不接流量</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>2. 告警规则：基于症状，不基于症状的原因</strong>：</p><div class="language-yaml line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groups</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">service</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">HighErrorRate</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    expr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sum(rate(http_requests_total{status=~&quot;5..&quot;}[5m]))</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">          / sum(rate(http_requests_total[5m])) &gt; 0.02</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">5m</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 持续 5 分钟才报，抖动不触发</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">severity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">page</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># page=叫醒, ticket=工作时间处理</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    annotations</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{ $labels.service }} 5xx 比例超过 2%&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DiskAlmostFull</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    expr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node_filesystem_avail_bytes / node_filesystem_size_bytes &lt; 0.15</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10m</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">severity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ticket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>要点：<code>for: 5m</code> 这类<strong>持续时间</strong>是第一道降噪——瞬时尖峰不报警；阈值从历史数据的基线来（P95 + 安全余量），不是拍脑袋；<strong>告警必须指向行动</strong>，写不出&quot;该做什么&quot;的规则先不上线。</p><p><strong>3. 告警降噪与路由</strong>：</p><ul><li><strong>分级</strong>：<code>page</code>（电话/短信，半夜也要醒）只留给「用户受影响且需要立即处理」；<code>ticket</code>（IM 群，工作时间处理）给资源趋势、证书临期这类；</li><li><strong>抑制</strong>：主机挂了 → 该主机上所有服务告警自动抑制，一条顶一百条；</li><li><strong>去重合并</strong>：同一告警在恢复前不重复发，Alertmanager 的 <code>group_by</code> 把同源告警打包；</li><li><strong>值班路由</strong>：按服务归属路由到值班人，非工作时间升级链（值班没响应 → 升级到备班）；</li><li><strong>定期回顾</strong>：每月过一遍告警列表，删掉从未处理过的规则——它们只在消耗信任。</li></ul><p><strong>4. 值班与处置流程</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>告警触达 → 5 分钟内 ACK（表明有人接）</span></span>
<span class="line"><span>  → 看板定级：影响面多大？(拨测/错误率/大盘)</span></span>
<span class="line"><span>  → 止血优先：回滚 / 摘流量 / 扩容 / 重启，先恢复再定位</span></span>
<span class="line"><span>  → 恢复后 ACK 关闭，24h 内补事后复盘（时间线 + 根因 + 改进项）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>两个原则：<strong>止血先于定位</strong>——能回滚就先回滚，根因可以事后查；<strong>复盘对事不对人</strong>——没有改进项的复盘等于没开。</p><h2 id="落地效果-示意" tabindex="-1">落地效果（示意） <a class="header-anchor" href="#落地效果-示意" aria-label="Permalink to “落地效果（示意）”">​</a></h2><ul><li>三层数据打通后，排查从「登机器翻日志猜」变成按 trace_id 从告警跳到日志、再跳到链路，定位路径固定；</li><li>分级 + 抑制 + 持续时间三板斧上线后，告警数量收敛，<code>page</code> 级告警基本条条需要处理；</li><li>健康检查分层后，依赖抖动不再引发连锁重启，故障被隔离在单点；</li><li>值班有明确的 ACK 时限和升级链，「告警发了没人管」的窗口被流程兜住。</li></ul><p>（以上为方案效果示意，非生产统计数据。）</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>监控告警的骨架：<strong>日志/指标/链路三层数据</strong>支撑定位，<strong>健康检查分层</strong>区分重启与摘流，<strong>基于症状的告警规则 + 持续时间</strong>过滤抖动，<strong>分级/抑制/去重</strong>控制噪声，<strong>值班 ACK + 止血优先 + 事后复盘</strong>闭环处置。判断标准很简单——每条半夜响起的告警，值班人都认为「值得被叫醒」，这套体系才算及格。</p>`,28)])])}const c=a(t,[["render",l]]);export{g as __pageData,c as default};
